-- chain_36_commerce_cohort_attribution_time_series_market_inventory
WITH selected_customers AS (SELECT * FROM customers WHERE cid>=1 AND cid<91),
oo AS (SELECT o.* FROM orders o JOIN selected_customers c ON o.cid=c.cid WHERE o.day BETWEEN 0 AND 55-1),
ee AS (SELECT e.* FROM events e JOIN selected_customers c ON e.cid=c.cid WHERE e.day BETWEEN 0 AND 55-1),

pay_ok AS (SELECT oid,SUM(CASE WHEN success=1 THEN paid ELSE 0 END) paid FROM payments GROUP BY oid),
refund_ok AS (SELECT oid,SUM(refunded) refund FROM refunds GROUP BY oid),
commerce_order AS (SELECT o.*,COALESCE(p.paid,0)-COALESCE(r.refund,0) net FROM oo o LEFT JOIN pay_ok p ON o.oid=p.oid LEFT JOIN refund_ok r ON o.oid=r.oid),
commerce_customer AS (SELECT cid,SUM(net) x,AVG(amount-cost) y,SUM(amount-net)/NULLIF(SUM(amount),0) z FROM commerce_order WHERE cancelled=0 GROUP BY cid),

cohort_days AS (SELECT DISTINCT cid,day FROM ee),
cohort_seq AS (SELECT cid,day,day-CAST(ROW_NUMBER() OVER(PARTITION BY cid ORDER BY day) AS BIGINT) island FROM cohort_days),
cohort_streak AS (SELECT cid,island,COUNT(*) n FROM cohort_seq GROUP BY cid,island),
cohort_longest AS (SELECT cid,MAX(n) streak FROM cohort_streak GROUP BY cid),
cohort_session AS (SELECT cid,session_id,MIN(CASE WHEN kind=0 THEN day END) viewed,MAX(CASE WHEN kind=3 THEN day END) purchased FROM ee GROUP BY cid,session_id),
cohort_conv_rate AS (SELECT cid,AVG(CAST(CASE WHEN purchased>=viewed THEN 1 ELSE 0 END AS DOUBLE)) conv_rate FROM cohort_session GROUP BY cid),
cohort_customer AS (SELECT a.cid,CAST(a.streak AS DOUBLE) x,COALESCE(b.conv_rate,0) y,CAST(55-MAX(e.day) AS DOUBLE) z FROM cohort_longest a LEFT JOIN cohort_conv_rate b ON a.cid=b.cid JOIN ee e ON a.cid=e.cid GROUP BY a.cid,a.streak,b.conv_rate),

attribution_touch AS (SELECT o.cid,o.oid,o.amount,e.kind,EXP(-CAST(0.01 AS DOUBLE)*(o.day-e.day)) w FROM oo o JOIN ee e ON o.cid=e.cid AND e.day BETWEEN o.day-7 AND o.day),
attribution_weight AS (SELECT cid,oid,amount,kind,w,SUM(w) OVER(PARTITION BY oid) total FROM attribution_touch),
attribution_channel AS (SELECT cid,kind,SUM(amount*w/total) rev FROM attribution_weight GROUP BY cid,kind),
attribution_probability AS (SELECT cid,kind,rev,rev/NULLIF(SUM(rev) OVER(PARTITION BY cid),0) p FROM attribution_channel),
attribution_customer AS (SELECT cid,SUM(rev) x,SUM(rev*kind)/NULLIF(SUM(rev),0) y,-SUM(p*LN(NULLIF(p,0))) z FROM attribution_probability GROUP BY cid),

time_daily AS (SELECT cid,day,SUM(amount) revenue FROM oo WHERE cancelled=0 GROUP BY cid,day),
time_grid AS (SELECT c.cid,d.day,COALESCE(a.revenue,0) revenue FROM selected_customers c CROSS JOIN calendar d LEFT JOIN time_daily a ON c.cid=a.cid AND d.day=a.day WHERE d.day BETWEEN 0 AND 55-1),
time_rolling AS (SELECT cid,day,revenue,AVG(revenue) OVER(PARTITION BY cid ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) ma FROM time_grid),
time_delta AS (SELECT cid,day,revenue,ma,ma-LAG(ma) OVER(PARTITION BY cid ORDER BY day) delta FROM time_rolling),
time_regime AS (SELECT cid,day,revenue,ma,delta,AVG(delta) OVER(PARTITION BY cid ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) trend FROM time_delta),
time_series_customer AS (SELECT cid,AVG(ma) x,STDDEV_POP(delta) y,SUM(COALESCE(trend,0)) z FROM time_regime GROUP BY cid),

market_lag AS (SELECT asset,day,close_price,LAG(close_price) OVER(PARTITION BY asset ORDER BY day) prev FROM market),
market_returns AS (SELECT asset,day,close_price,LN(close_price/prev) ret FROM market_lag WHERE day BETWEEN 0 AND 180),
market_rolling AS (SELECT asset,day,close_price,ret,AVG(ret) OVER(PARTITION BY asset ORDER BY day ROWS BETWEEN 20 PRECEDING AND CURRENT ROW) ma,VAR_POP(ret) OVER(PARTITION BY asset ORDER BY day ROWS BETWEEN 20 PRECEDING AND CURRENT ROW) rv FROM market_returns),
market_peak AS (SELECT asset,day,ret,ma,rv,close_price/MAX(close_price) OVER(PARTITION BY asset ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)-1 drawdown FROM market_rolling),
market_asset AS (SELECT asset,SUM(ret) growth,AVG(rv) volatility,MIN(drawdown) drawdown FROM market_peak GROUP BY asset),
market_customer AS (SELECT c.cid,a.growth*COALESCE(c.credit,0) x,a.volatility y,a.drawdown z FROM selected_customers c JOIN market_asset a ON MOD(c.cid,8)=a.asset),

inventory_period AS (SELECT i.pid,AVG(CAST(on_hand AS DOUBLE)) stock,AVG(CAST(CASE WHEN on_hand<lead_days THEN 1 ELSE 0 END AS DOUBLE)) shortage,MAX(lead_days) lead FROM inventory i WHERE day BETWEEN 0 AND 55-1 GROUP BY i.pid),
inventory_category AS (SELECT p.category,AVG(i.shortage) shortage,AVG(i.stock) stock,AVG(CAST(i.lead AS DOUBLE)) lead FROM inventory_period i JOIN products p ON i.pid=p.pid GROUP BY p.category),
inventory_basket AS (SELECT o.cid,p.category,SUM(i.qty*i.price) spend FROM oo o JOIN items i ON o.oid=i.oid JOIN products p ON i.pid=p.pid GROUP BY o.cid,p.category),
inventory_exposure AS (SELECT a.cid,a.spend,b.shortage,b.stock,b.lead FROM inventory_basket a JOIN inventory_category b ON a.category=b.category),
inventory_customer AS (SELECT cid,SUM(spend*shortage)/NULLIF(SUM(spend),0) x,SUM(spend*stock)/NULLIF(SUM(spend),0) y,SUM(spend*lead)/NULLIF(SUM(spend),0) z FROM inventory_exposure GROUP BY cid),
feature_raw AS (SELECT c.cid,c.tier,c.region,COALESCE(b0.x,0) f1,COALESCE(b0.y,0) f2,COALESCE(b0.z,0) f3,COALESCE(b1.x,0) f4,COALESCE(b1.y,0) f5,COALESCE(b1.z,0) f6,COALESCE(b2.x,0) f7,COALESCE(b2.y,0) f8,COALESCE(b2.z,0) f9,COALESCE(b3.x,0) f10,COALESCE(b3.y,0) f11,COALESCE(b3.z,0) f12,COALESCE(b4.x,0) f13,COALESCE(b4.y,0) f14,COALESCE(b4.z,0) f15,COALESCE(b5.x,0) f16,COALESCE(b5.y,0) f17,COALESCE(b5.z,0) f18 FROM selected_customers c LEFT JOIN commerce_customer b0 ON c.cid=b0.cid LEFT JOIN cohort_customer b1 ON c.cid=b1.cid LEFT JOIN attribution_customer b2 ON c.cid=b2.cid LEFT JOIN time_series_customer b3 ON c.cid=b3.cid LEFT JOIN market_customer b4 ON c.cid=b4.cid LEFT JOIN inventory_customer b5 ON c.cid=b5.cid),
feature_normalized AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(f1-AVG(f1) OVER())/COALESCE(NULLIF(STDDEV_POP(f1) OVER(),0),1)+(f2-AVG(f2) OVER())/COALESCE(NULLIF(STDDEV_POP(f2) OVER(),0),1)+(f3-AVG(f3) OVER())/COALESCE(NULLIF(STDDEV_POP(f3) OVER(),0),1)+(f4-AVG(f4) OVER())/COALESCE(NULLIF(STDDEV_POP(f4) OVER(),0),1)+(f5-AVG(f5) OVER())/COALESCE(NULLIF(STDDEV_POP(f5) OVER(),0),1)+(f6-AVG(f6) OVER())/COALESCE(NULLIF(STDDEV_POP(f6) OVER(),0),1)+(f7-AVG(f7) OVER())/COALESCE(NULLIF(STDDEV_POP(f7) OVER(),0),1)+(f8-AVG(f8) OVER())/COALESCE(NULLIF(STDDEV_POP(f8) OVER(),0),1)+(f9-AVG(f9) OVER())/COALESCE(NULLIF(STDDEV_POP(f9) OVER(),0),1)+(f10-AVG(f10) OVER())/COALESCE(NULLIF(STDDEV_POP(f10) OVER(),0),1)+(f11-AVG(f11) OVER())/COALESCE(NULLIF(STDDEV_POP(f11) OVER(),0),1)+(f12-AVG(f12) OVER())/COALESCE(NULLIF(STDDEV_POP(f12) OVER(),0),1)+(f13-AVG(f13) OVER())/COALESCE(NULLIF(STDDEV_POP(f13) OVER(),0),1)+(f14-AVG(f14) OVER())/COALESCE(NULLIF(STDDEV_POP(f14) OVER(),0),1)+(f15-AVG(f15) OVER())/COALESCE(NULLIF(STDDEV_POP(f15) OVER(),0),1)+(f16-AVG(f16) OVER())/COALESCE(NULLIF(STDDEV_POP(f16) OVER(),0),1)+(f17-AVG(f17) OVER())/COALESCE(NULLIF(STDDEV_POP(f17) OVER(),0),1)+(f18-AVG(f18) OVER())/COALESCE(NULLIF(STDDEV_POP(f18) OVER(),0),1) normalized_score FROM feature_raw),
feedback_0 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,1/(1+EXP(-LEAST(30,GREATEST(-30,normalized_score/18)))) score FROM feature_normalized),
feedback_1 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1300 AS DOUBLE)*score+CAST(0.0040 AS DOUBLE)*LN(1+ABS(f2)))))))/2 score FROM feedback_0),
feedback_2 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1400 AS DOUBLE)*score+CAST(0.0050 AS DOUBLE)*LN(1+ABS(f3)))))))/2 score FROM feedback_1),
feedback_3 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1500 AS DOUBLE)*score+CAST(0.0060 AS DOUBLE)*LN(1+ABS(f4)))))))/2 score FROM feedback_2),
feedback_4 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1600 AS DOUBLE)*score+CAST(0.0070 AS DOUBLE)*LN(1+ABS(f5)))))))/2 score FROM feedback_3),
feedback_5 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1700 AS DOUBLE)*score+CAST(0.0030 AS DOUBLE)*LN(1+ABS(f6)))))))/2 score FROM feedback_4),
feedback_6 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1800 AS DOUBLE)*score+CAST(0.0040 AS DOUBLE)*LN(1+ABS(f7)))))))/2 score FROM feedback_5),
feedback_7 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1200 AS DOUBLE)*score+CAST(0.0050 AS DOUBLE)*LN(1+ABS(f8)))))))/2 score FROM feedback_6),
feedback_8 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1300 AS DOUBLE)*score+CAST(0.0060 AS DOUBLE)*LN(1+ABS(f9)))))))/2 score FROM feedback_7),
feedback_9 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1400 AS DOUBLE)*score+CAST(0.0070 AS DOUBLE)*LN(1+ABS(f10)))))))/2 score FROM feedback_8),
feedback_10 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1500 AS DOUBLE)*score+CAST(0.0030 AS DOUBLE)*LN(1+ABS(f11)))))))/2 score FROM feedback_9),
feedback_11 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1600 AS DOUBLE)*score+CAST(0.0040 AS DOUBLE)*LN(1+ABS(f12)))))))/2 score FROM feedback_10),
feedback_12 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1700 AS DOUBLE)*score+CAST(0.0050 AS DOUBLE)*LN(1+ABS(f13)))))))/2 score FROM feedback_11),
feedback_13 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1800 AS DOUBLE)*score+CAST(0.0060 AS DOUBLE)*LN(1+ABS(f14)))))))/2 score FROM feedback_12),
feedback_14 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1200 AS DOUBLE)*score+CAST(0.0070 AS DOUBLE)*LN(1+ABS(f15)))))))/2 score FROM feedback_13),
feedback_15 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1300 AS DOUBLE)*score+CAST(0.0030 AS DOUBLE)*LN(1+ABS(f16)))))))/2 score FROM feedback_14),
feedback_16 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1400 AS DOUBLE)*score+CAST(0.0040 AS DOUBLE)*LN(1+ABS(f17)))))))/2 score FROM feedback_15),
feedback_17 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1500 AS DOUBLE)*score+CAST(0.0050 AS DOUBLE)*LN(1+ABS(f18)))))))/2 score FROM feedback_16),
feedback_18 AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,(score+1/(1+EXP(-LEAST(30,GREATEST(-30,CAST(0.1600 AS DOUBLE)*score+CAST(0.0060 AS DOUBLE)*LN(1+ABS(f1)))))))/2 score FROM feedback_17),
customer_rank AS (SELECT cid,tier,region,f1,f2,f3,f4,f5,f6,f7,f8,f9,f10,f11,f12,f13,f14,f15,f16,f17,f18,score,ROW_NUMBER() OVER(PARTITION BY tier ORDER BY ROUND(score,9) DESC,cid) rn,NTILE(3) OVER(PARTITION BY tier ORDER BY ROUND(score,9),cid) bucket FROM feedback_18),
budget_join AS (SELECT r.*,t.revenue_target,t.risk_budget FROM customer_rank r JOIN targets t ON r.tier=t.tier AND t.week=FLOOR((55-1)/7))
SELECT cid,tier,rn,score,f1,f2,f3,f1+f2+f3+f4+f5+f6+f7+f8+f9+f10+f11+f12+f13+f14+f15+f16+f17+f18 feature_sum FROM budget_join WHERE rn<=2 ORDER BY tier,rn;
